import{S as r}from"./SciencePage-c6eb4da1.js";import{o as s,c as o,u as e}from"./index-cc76a1f4.js";import"./PageHead-4cd6acb7.js";import"./_plugin-vue_export-helper-88cb6d52.js";import"./RibbonMark-04330ea1.js";const n="/mentally/assets/反应_背景-eedbe6e2.webp",_={__name:"more",setup(a){const t=[{title:"一、什么是反应时",paragraphs:["反应时（Reaction Time, RT）指从刺激呈现到做出明确外显反应之间的时间间隔，是衡量感知觉加工、注意分配、决策速度与动作执行的核心行为指标。19 世纪中叶，唐德斯（F. C. Donders）建立了反应时的实验室测量范式，它也成为认知心理学的奠基方法之一。","本项目的基础模式采用<strong>简单视觉反应时</strong>范式：单一目标刺激出现后立即反应，测量「看见 — 判断 — 动作」的整条通路耗时。"]},{title:"二、进阶模式测的是什么",paragraphs:["舒尔特方格（Schulte Grid）要求按 1 到 25 的顺序依次点击，考察的是<strong>视觉搜索效率</strong>与<strong>注意的稳定性</strong>：既要在有限视野内快速定位目标，又要抑制无关数字的干扰，同时保持节奏不乱。","它与基础模式互补：基础模式测量单次反应的「启动速度」，舒尔特方格测量持续几十秒的「注意维持与搜索效率」。"]},{title:"三、本次挑战记录了哪些指标",list:["<strong>平均反应时</strong>：所有有效轮次的平均水平，越小代表加工越快。","<strong>标准差与变异系数 CV</strong>：衡量几轮之间的波动，CV 越小说明注意越稳定；比单看平均值更能反映状态。","<strong>抢按次数</strong>：刺激尚未出现就按键，反映预期判断偏早，这部分数据不计入平均值。","<strong>未反应次数</strong>：超过作答窗口仍未按键，多与注意力短暂离线、设备延迟有关。","<strong>点错次数</strong>（进阶模式）：反映目标定位与干扰抑制的准确性。"]},{title:"四、怎样看待自己的成绩",paragraphs:["反应时受睡眠、咖啡因、情绪状态、屏幕刷新率与鼠标键盘延迟等因素影响，个体差异与日内波动都很大。页面给出的区间只是便于理解的<strong>科普参考</strong>，不构成任何能力评定或病理判断。","想得到稳定结论，可以在相近条件下（同样的设备、相近的时间段）测 2 到 3 次，比较平均值与波动，而不是纠结某一次的数字。"]}];return(g,i)=>(s(),o(r,{title:"反应速度的科学原理",subtitle:"从刺激出现到按下按钮，大脑经历了什么",art:e(n),sections:t},null,8,["art"]))}};export{_ as default};
